package ru.truetv.launcher;
import android.app.*;
import android.content.*;
import android.os.*;
import java.io.*;
/** Only disposable emulator: actual detached helper status/start/stop, no owner device or firmware writes. */
public final class VolumeHelperCheck extends Instrumentation {
 private String probeText(){VmWindows.clear(this);android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root==null)return "";try{java.util.ArrayList<android.view.accessibility.AccessibilityNodeInfo> nodes=new java.util.ArrayList<>();ControlService.collect(root,nodes,0);String value="";for(android.view.accessibility.AccessibilityNodeInfo n:nodes){String text=String.valueOf(n.getText());if(text.startsWith("VOLUME_PROBE "))value=text;n.recycle();}return value;}catch(Exception e){return "";}}
 private static int count(String text,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile(key+"=([0-9]+)").matcher(text);return m.find()?Integer.parseInt(m.group(1)):-1;}
 private void edge(ExpertBackend adb,boolean down)throws Exception{ShellReply r=adb.shell("sendevent /dev/input/event1 1 115 "+(down?"1":"0")+" && sendevent /dev/input/event1 0 0 0");if(r.code!=0)throw new AssertionError(r.text);}
 private String endpoint="10.0.2.2:5555";
 public void onCreate(Bundle b){super.onCreate(b);endpoint=b.getString("endpoint",endpoint);start();}
 public void onStart(){Bundle result=new Bundle();StringBuilder report=new StringBuilder();ExpertBackend adb=null;String apk=null;try{if(!(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK")))throw new AssertionError("VM only");Context c=getTargetContext();VmWindows.prepare(this);adb=new ExpertBackend(c,false,endpoint);apk=c.getApplicationInfo().sourceDir;report.append("Verified same-device ADB uid=").append(adb.shell("id -u").text.trim()).append('\n');ShellReply stop=adb.shell(VolumeCommand.stop(apk));if(stop.code!=0)throw new AssertionError(stop.text);Thread.sleep(500);ShellReply launch=adb.shell(VolumeCommand.start(apk));if(launch.code!=0)throw new AssertionError(launch.text);Thread.sleep(1000);ShellReply state=adb.shell(VolumeCommand.status(apk));if(state.code!=0||!state.text.trim().equals("TRUE_TV_VOLUME_RUNNING"))throw new AssertionError("not running: "+state.text+" log="+adb.shell("tail -c 2048 "+PackagePolicy.quote(VolumeCommand.BASE+".log")).text);report.append("PASS detached own-APK helper running through actual ADB\n");adb.close();adb=new ExpertBackend(c,false,endpoint);state=adb.shell(VolumeCommand.status(apk));if(state.code!=0||!state.text.trim().equals("TRUE_TV_VOLUME_RUNNING"))throw new AssertionError("did not survive connection closure");report.append("PASS helper survives ADB connection closure\n");String devices=adb.shell("getevent -lp").text;if(!devices.contains("/dev/input/event1")||!devices.contains("qwerty2")||!devices.contains("KEY_VOLUMEUP"))throw new AssertionError("VM keyboard fixture unavailable");c.startActivity(new Intent().setComponent(new ComponentName("ru.truetv.probe","ru.truetv.probe.VolumeProbe")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long ready=SystemClock.uptimeMillis()+12000;while(probeText().isEmpty()&&SystemClock.uptimeMillis()<ready)Thread.sleep(80);if(probeText().isEmpty())throw new AssertionError("volume input sink not visible; root="+String.valueOf(getUiAutomation().getRootInActiveWindow()));try{edge(adb,true);Thread.sleep(2000);}finally{edge(adb,false);}Thread.sleep(500);String observed=probeText();int extra=count(observed,"SYNTHETIC_DOWN");if(extra<1||count(observed,"SYNTHETIC_UP")<1)throw new AssertionError("no balanced synthetic repeat: "+observed);Thread.sleep(500);if(count(probeText(),"SYNTHETIC_DOWN")!=extra)throw new AssertionError("repeat continued after UP");report.append("PASS raw VM volume DOWN/UP produced balanced synthetic repeats; none after release\n");stop=adb.shell(VolumeCommand.stop(apk));if(stop.code!=0)throw new AssertionError(stop.text);boolean ended=false;for(int i=0;i<12;i++){Thread.sleep(250);state=adb.shell(VolumeCommand.status(apk));if(state.code==0&&state.text.trim().equals("TRUE_TV_VOLUME_STOPPED")){ended=true;break;}}if(!ended)throw new AssertionError("stop not confirmed");report.append("PASS explicit stop releases own helper lock\n");int before=count(probeText(),"SYNTHETIC_DOWN");try{edge(adb,true);Thread.sleep(1000);}finally{edge(adb,false);}Thread.sleep(300);if(count(probeText(),"SYNTHETIC_DOWN")!=before)throw new AssertionError("stopped helper still repeats");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);report.append("PASS stopped helper adds no repeats on another raw hold\nNo physical remote/audio/CEC behavior claim.");result.putBoolean("passed",true);result.putString("report",report.toString());}catch(Throwable failure){StringWriter s=new StringWriter();failure.printStackTrace(new PrintWriter(s));result.putBoolean("passed",false);result.putString("report",report+s.toString());}finally{if(adb!=null){try{if(apk!=null){try{edge(adb,false);}catch(Exception ignored){}adb.shell(VolumeCommand.stop(apk));}adb.close();}catch(Exception ignored){}}}finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
